import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily } = loadFont();



export type AnimatedBadgeProps = Record<string, any>;

const AnimatedBadge: React.FC<AnimatedBadgeProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  prefixText = "Strategy",
  totalSteps = 4,
  badgeColor = "#243721",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing baseline
  const s = Math.min(width, height);
  const fontSize = s * 0.045;
  const lineHeight = fontSize * 1.2;

  // Animation timing calculations
  const durationInFrames = durationInSeconds * fps;
  const stepDuration = Math.floor(durationInFrames / totalSteps);

  // Intro Slide Animation
  const badgeSlideIn = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 90, mass: 0.8 },
  });

  const badgeY = interpolate(badgeSlideIn, [0, 1], [250, 0]);
  const badgeOpacity = interpolate(badgeSlideIn, [0, 1], [0, 1]);

  // Step Transitions (Pure frame-based array mapped to springs)
  const stepTransitions = Array.from({ length: totalSteps - 1 }).map((_, i) => {
    const stepStartFrame = (i + 1) * stepDuration;
    return spring({
      fps,
      frame: Math.max(0, frame - stepStartFrame),
      config: { damping: 16, stiffness: 120, mass: 0.8 },
    });
  });

  // Calculate vertical translation for the sliding numbers
  const activeStepSum = stepTransitions.reduce((a, b) => a + b, 0);
  const groupTranslateY = -(activeStepSum * lineHeight);

  // Calculate subtle scale pulse on number change
  const scalePulseSum = stepTransitions.reduce((acc, transition) => {
    const pulse = interpolate(transition, [0, 0.5, 1], [0, 1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    return acc + pulse;
  }, 0);
  const numberScale = 1 + scalePulseSum * 0.25;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          left: width * 0.08,
          bottom: height * 0.12,
          transform: `translateY(${badgeY}px)`,
          opacity: badgeOpacity,
          backgroundColor: badgeColor,
          color: textColor,
          padding: `${s * 0.02}px ${s * 0.04}px`,
          borderRadius: 999,
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: s * 0.015,
          fontFamily,
          fontSize,
          fontWeight: 600,
          boxShadow: "0px 12px 40px rgba(0, 0, 0, 0.2)",
          border: `1px solid ${textColor}15`,
        }}
      >
        <span style={{ transition: "none" }}>{prefixText}</span>

        {/* Sliding Number Container */}
        <div
          style={{
            height: lineHeight,
            overflow: "hidden",
            display: "inline-flex",
            flexDirection: "column",
            position: "relative",
            width: fontSize * 1.1,
            justifyContent: "flex-start",
            alignItems: "center",
            transform: `scale(${numberScale})`,
            transition: "none",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              transform: `translateY(${groupTranslateY}px)`,
              transition: "none", // Critical: prevents CSS transitions from conflicting with frame-based logic
            }}
          >
            {Array.from({ length: totalSteps }).map((_, i) => (
              <span
                key={i}
                style={{
                  height: lineHeight,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: "100%",
                  transition: "none",
                }}
              >
                {i + 1}
              </span>
            ))}
          </div>
        </div>

        <span style={{ transition: "none" }}>of {totalSteps}</span>
      </div>
    </AbsoluteFill>
  );
};

export default AnimatedBadge;